float3 p = WorldPosition * TriplanarWorldScale;
float3 q = WorldPosition / max(MacroScale, 1.0);
float detailTiling = max(DetailTiling, 0.01);
float macroA = sin(dot(q, float3(0.73, 0.31, -0.61)) * 6.2831853);
float macroB = sin(dot(q, float3(-0.29, 0.89, 0.37)) * 6.2831853 + 1.618);
float macroC = sin(dot(q, float3(0.53, -0.47, 0.79)) * 6.2831853 + 0.618);
float3 detailQ = q * detailTiling;
float3 detailPhase = float3(sin(dot(detailQ, float3(1.17,-0.41,0.23))*6.2831853),sin(dot(detailQ,float3(-0.37,1.09,0.51))*6.2831853+2.094),sin(dot(detailQ,float3(0.43,0.19,1.21))*6.2831853+4.189));
float3 macroDirection = normalize(float3(macroA-macroB, macroB-macroC, macroC-macroA) + 0.0001);
float amplitude = saturate(MacroVariationStrength) * (0.018 + 0.082 * saturate(DetailStrength));
return p + macroDirection * amplitude + detailPhase * amplitude * 0.35;

float2 Pivot = float2(0.5, 0.5);
float2 c = UV - Pivot;
float ang = Rotation * 6.28318530718;
float s, co;
sincos(ang, s, co);
float2 r = float2(co * c.x - s * c.y, s * c.x + co * c.y);
return r + Pivot + float2(OffsetU, OffsetV);

